INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20910P7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A chemist has $300$ milliliters of a solution that is $11\\%$ acid by volume. She adds $d$ milliliters of pure acid to the solution so that the resulting mixture is $25\\%$ acid by volume. What is the value of $d$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '56', ARRAY['56'], E'The initial amount of acid is $0.11 \\times 300 = 33$ mL. After adding $d$ mL of pure acid, the total acid is $33 + d$ and the total volume is $300 + d$. Setting up the equation: $\\frac{33 + d}{300 + d} = 0.25$. Cross-multiplying gives $33 + d = 0.25(300 + d) = 75 + 0.25d$. Solving: $d - 0.25d = 75 - 33$, so $0.75d = 42$, and $d = \\frac{42}{0.75} = 56$. A common error is forgetting to include $d$ in the denominator (total volume), which leads to $\\frac{33 + d}{300} = 0.25$ and $d = 42$. Another error is using $0.11d$ instead of $d$ for the added acid, treating it as $11\\%$ acid rather than pure acid.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21VLA7C', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'What are all values of $x$ that satisfy the inequality $\\frac{17 - 5x}{2} > 6$?', NULL, $lyceon_json$[{"key":"A","text":"$x < 1$"},{"key":"B","text":"$x > 1$"},{"key":"C","text":"$x > -1$"},{"key":"D","text":"$x < \\frac{1}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiply both sides by $2$: $17 - 5x > 12$. Subtract $17$: $-5x > -5$. Divide by $-5$ and flip the inequality: $x < 1$. The answer $x > 1$ results from forgetting to reverse the inequality sign when dividing by a negative number. The answer $x > -1$ comes from a sign slip when computing $-5 \\div (-5)$, incorrectly yielding $-1$ instead of $1$. The answer $x < \\frac{1}{2}$ arises from incorrectly interpreting $\\frac{17 - 5x}{2}$ as $\\frac{17}{2} - 5x$, dividing only the first term by $2$ rather than the entire numerator, which leads to $8.5 - 5x > 6$ and ultimately $x < 0.5$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2266SOE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 3(x + 4)^2 - 5$. Which of the following correctly describes the graph of $g$ compared to the graph of $y = x^2$?', NULL, $lyceon_json$[{"key":"A","text":"The graph is shifted $4$ units to the left, vertically stretched by a factor of $3$, and shifted $5$ units down."},{"key":"B","text":"The graph is shifted $4$ units to the right, vertically stretched by a factor of $3$, and shifted $5$ units down."},{"key":"C","text":"The graph is shifted $4$ units to the left, vertically stretched by a factor of $3$, and shifted $5$ units up."},{"key":"D","text":"The graph is shifted $4$ units to the right, vertically compressed by a factor of $\\frac{1}{3}$, and shifted $5$ units down."}]$lyceon_json$::jsonb, 'A', NULL, E'In $g(x) = 3(x + 4)^2 - 5$, the term $x + 4$ means $x - (-4)$, so the graph shifts $4$ units to the left. The coefficient $3$ (greater than $1$) vertically stretches the parabola by a factor of $3$. The $-5$ shifts the graph $5$ units down. The description claiming a shift $4$ units to the right misreads the sign of the horizontal translation, confusing $x + 4$ with $x - 4$. The description claiming a shift $5$ units up reverses the sign of the vertical translation. The description involving a vertical compression by $\\frac{1}{3}$ confuses a coefficient greater than $1$ (which stretches) with a compression.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22WHFZ1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = -1.4x + 89$ models the relationship between the number of hours a student spends watching television per week, $x$, and the student''s test score, $y$. What is the best interpretation of $-1.4$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of television watched per week, the predicted test score decreases by $1.4$ points."},{"key":"B","text":"For each additional hour of television watched per week, the predicted test score increases by $1.4$ points."},{"key":"C","text":"A student who watches no television is predicted to score $1.4$ points on the test."},{"key":"D","text":"For each $1$-point increase in test score, the student watches $1.4$ fewer hours of television per week."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $y = -1.4x + 89$, the coefficient $-1.4$ is the slope, which represents the predicted change in $y$ (test score) for each unit increase in $x$ (hours of television). Since the slope is negative, the predicted test score decreases by $1.4$ points for each additional hour of television watched. The distractor stating the score increases by $1.4$ ignores the negative sign of the slope. The distractor about scoring $1.4$ points confuses the slope with the $y$-intercept ($89$ is the predicted score when $x = 0$). The distractor about $1$-point increases in test score reverses the roles of the independent and dependent variables.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23G49TN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A car travels $203$ miles using $7$ gallons of gasoline. At the same rate of fuel consumption, how many gallons of gasoline are needed to travel $493$ miles?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The car''s fuel efficiency is $\\frac{203}{7} = 29$ miles per gallon. To find the gallons needed for $493$ miles, divide: $\\frac{493}{29} = 17$ gallons. A common error is to set up the proportion incorrectly, for example computing $\\frac{493}{203} \\times 203$ instead of $\\frac{493}{203} \\times 7$, or making an arithmetic error in the long division.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23SZXX7', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'$$13x + 47 = 112$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23UJDLX', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a bookstore, Mia buys $3$ novels and $2$ graphic novels for a total of $\\$43$. Javier buys $1$ novel and $4$ graphic novels for a total of $\\$51$. What is the price, in dollars, of one graphic novel?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Let $n$ be the price of a novel and $g$ be the price of a graphic novel. The system is $3n + 2g = 43$ and $n + 4g = 51$. From the second equation, $n = 51 - 4g$. Substituting into the first equation: $3(51 - 4g) + 2g = 43$, so $153 - 12g + 2g = 43$, giving $-10g = -110$ and $g = 11$. Verification: $n = 51 - 44 = 7$; then $3(7) + 2(11) = 21 + 22 = 43$ and $7 + 4(11) = 7 + 44 = 51$, both correct. A common error is solving for the novel price ($7$) instead of the graphic novel price. Another error path is mishandling distribution: computing $3(51) - 4g + 2g$ instead of $3(51) - 12g + 2g$, which yields an incorrect value of $g$.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2451W24', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that people who eat breakfast daily have, on average, lower body mass index (BMI) than people who skip breakfast. The data came from a survey of 2,400 adults who self-reported their eating habits. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast daily causes a lower BMI."},{"key":"B","text":"There is an association between eating breakfast daily and having a lower BMI."},{"key":"C","text":"Skipping breakfast causes a higher BMI."},{"key":"D","text":"Adults who eat breakfast exercise more than adults who skip breakfast."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is observational (a survey with self-reported data and no random assignment to treatment groups), it can only establish an association, not a causal relationship. The distractor claiming breakfast causes lower BMI incorrectly infers causation from an observational study. The distractor claiming skipping breakfast causes higher BMI similarly makes an unsupported causal claim from observational data. The distractor about exercise introduces an unsubstantiated claim not supported by the data described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25CTJ59', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of the equation $x^2 = 289$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Taking the square root of both sides gives $x = \\pm\\sqrt{289}$. Since $17 \\times 17 = 289$, we have $\\sqrt{289} = 17$. The question asks for the positive solution, so the answer is $17$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25KL30S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A shelf contains 11 fiction books and 7 nonfiction books. If one book is selected at random, what is the probability that it is a nonfiction book?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{7}{18}\\)"},{"key":"B","text":"\\(\\dfrac{11}{18}\\)"},{"key":"C","text":"\\(\\dfrac{7}{11}\\)"},{"key":"D","text":"\\(\\dfrac{7}{25}\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'There are 11 + 7 = 18 books total, and 7 are nonfiction, so the probability is 7/18. The distractor 11/18 results from selecting the fiction count instead of nonfiction. The distractor 7/11 uses the fiction count as the denominator rather than the total. The distractor 7/25 uses an incorrect total of 25 instead of 18.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM277NGCY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ cm and a height of $18$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$90\\pi \\text{ cm}^3$"},{"key":"B","text":"$180\\pi \\text{ cm}^3$"},{"key":"C","text":"$450\\pi \\text{ cm}^3$"},{"key":"D","text":"$900\\pi \\text{ cm}^3$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi(5)^2(18) = \\pi(25)(18) = 450\\pi$ cm$^3$. The expression $90\\pi$ results from using $\\pi r h = \\pi(5)(18) = 90\\pi$, forgetting to square the radius. The expression $180\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(5)(18) = 180\\pi$ instead of the volume formula. The expression $900\\pi$ results from doubling the correct volume, possibly from confusing with a different formula or squaring the height as well.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27CO2N2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $PQR$, angle $P$ measures $23^\\circ$. The exterior angle at vertex $R$ (formed by extending side $QR$ beyond $R$) measures $141^\\circ$. What is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '118', ARRAY['118'], E'The exterior angle at $R$ and the interior angle at $R$ are supplementary, so the interior angle at $R = 180^\\circ - 141^\\circ = 39^\\circ$. By the triangle angle sum, angle $Q = 180^\\circ - 23^\\circ - 39^\\circ = 118^\\circ$. Alternatively, by the exterior angle theorem, the exterior angle at $R$ equals the sum of the two non-adjacent interior angles: $141^\\circ = 23^\\circ + \\text{angle } Q$, so angle $Q = 141^\\circ - 23^\\circ = 118^\\circ$. A common error is computing $180^\\circ - 141^\\circ = 39^\\circ$ and reporting that as angle $Q$, confusing the interior angle at $R$ with angle $Q$. Another error is subtracting $23^\\circ$ from $180^\\circ$ directly to get $157^\\circ$, ignoring the information about the exterior angle.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28549PY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'At a veterinary clinic, 38% of patients are dogs, 27% are cats, and the rest are other animals. Among dogs, 15% have been diagnosed with a joint condition. Among cats, 9% have been diagnosed with the same joint condition, and among other animals, 4% have. Given that a randomly selected patient has the joint condition, what is the probability that the patient is a dog? (Round to the nearest hundredth.)', NULL, $lyceon_json$[{"key":"A","text":"0.57"},{"key":"B","text":"0.15"},{"key":"C","text":"0.38"},{"key":"D","text":"0.60"}]$lyceon_json$::jsonb, 'D', NULL, E'This requires Bayes'' theorem. The other animals make up 100% - 38% - 27% = 35%. P(joint condition) = 0.38(0.15) + 0.27(0.09) + 0.35(0.04) = 0.0570 + 0.0243 + 0.0140 = 0.0953. Then P(dog | joint condition) = 0.0570/0.0953 = 0.5981, which rounds to 0.60. The distractor 0.57 comes from dividing 0.0570 by 0.10 (rounding the denominator up) or a similar shortcut error. The distractor 0.15 confuses P(joint condition | dog) with P(dog | joint condition), reversing the conditional. The distractor 0.38 uses the unconditional probability of being a dog without applying Bayes'' theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28HI24L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, angle $P$ measures $47^\\circ$ and angle $Q$ measures $68^\\circ$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$55^\\circ$"},{"key":"B","text":"$65^\\circ$"},{"key":"C","text":"$75^\\circ$"},{"key":"D","text":"$115^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180^\\circ$. Therefore, angle $R = 180^\\circ - 47^\\circ - 68^\\circ = 65^\\circ$. The answer $55^\\circ$ results from a subtraction error such as computing $180 - 125 = 55$ instead of $180 - 115 = 65$. The answer $75^\\circ$ comes from miscomputing the sum $47 + 68$ as $105$ rather than $115$. The answer $115^\\circ$ results from stopping at the sum of the two known angles ($47 + 68 = 115$) without subtracting from $180^\\circ$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28OUI81', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(4) = 29$ and $g(11) = 78$, what is the value of $g(-3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-20', ARRAY['-20'], E'Using the two given values, the slope is $a = \\frac{g(11) - g(4)}{11 - 4} = \\frac{78 - 29}{7} = \\frac{49}{7} = 7$. Substituting into $g(4) = 7(4) + b = 29$ gives $28 + b = 29$, so $b = 1$. Therefore $g(x) = 7x + 1$. Evaluating at $x = -3$: $g(-3) = 7(-3) + 1 = -21 + 1 = -20$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29B9B33', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = (x - 7)^2 - 11$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $f(x) = (x - 7)^2 - 11$ is in vertex form $a(x - h)^2 + k$ with $h = 7$ and $k = -11$. Since $(x - 7)^2 \\geq 0$ for all real $x$, the minimum value of $f(x)$ is $-11$, achieved when $x = 7$. The value $-7$ confuses the $x$-coordinate of the vertex with the minimum output value. The value $7$ mistakes the $x$-coordinate of the vertex for the function''s minimum. The value $11$ incorrectly takes the absolute value of the vertical shift.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A3CNVU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 11x - 37$, what is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$-40$"},{"key":"B","text":"$33$"},{"key":"C","text":"$40$"},{"key":"D","text":"$114$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substitute $x = 7$: $f(7) = 11(7) - 37 = 77 - 37 = 40$. The distractor $-40$ arises from a sign error on the final result. The distractor $33$ results from an arithmetic slip computing $11 \\times 7$ as $70$ instead of $77$, giving $70 - 37 = 33$. The distractor $114$ comes from adding instead of subtracting: $77 + 37 = 114$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AH1BEK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$121\\pi$"},{"key":"D","text":"$132\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(11)^2 = 121\\pi$. The expression $11\\pi$ results from using $\\pi r$ instead of $\\pi r^2$, omitting the exponent. The expression $22\\pi$ results from using the circumference formula $2\\pi r = 2\\pi(11) = 22\\pi$ instead of the area formula. The expression $132\\pi$ results from an arithmetic error such as computing $11 \\times 12 = 132$ instead of $11 \\times 11 = 121$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ATV7O3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 400 registered voters and finds that 57% support a local bond measure, with a margin of error of 4.2 percentage points at a 95% confidence level. A second researcher surveys a random sample of 1,600 registered voters from the same population and obtains the same sample proportion. Which of the following best describes how the margin of error for the second survey compares to that of the first?', NULL, $lyceon_json$[{"key":"A","text":"The margin of error for the second survey is approximately half that of the first survey."},{"key":"B","text":"The margin of error for the second survey is approximately one-fourth that of the first survey."},{"key":"C","text":"The margin of error for the second survey is approximately equal to that of the first survey."},{"key":"D","text":"The margin of error for the second survey is approximately double that of the first survey."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Since the second sample (1,600) is 4 times the first (400), the margin of error decreases by a factor of the square root of 4, which is 2, making it approximately half the original. The distractor claiming one-fourth incorrectly treats the margin of error as inversely proportional to the sample size itself rather than its square root. The distractor claiming the margins are equal ignores the effect of sample size. The distractor claiming double reverses the relationship between sample size and margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CM6JJQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers want to test whether a new ergonomic keyboard reduces wrist pain in office workers. They recruit 130 volunteers from a large corporation and randomly assign 65 to use the new keyboard for 8 weeks and 65 to continue using their standard keyboard. At the end of the study, the group using the new keyboard reports significantly less wrist pain. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The new keyboard caused a reduction in wrist pain among the volunteers in the study."},{"key":"B","text":"The new keyboard will reduce wrist pain for all office workers."},{"key":"C","text":"There is an association between keyboard type and wrist pain, but causation cannot be established."},{"key":"D","text":"The reduction in wrist pain was likely due to the placebo effect rather than the keyboard."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study uses random assignment to treatment and control groups, it is an experiment, which can support a causal conclusion. The causal claim is limited to the volunteers in the study since they were not randomly selected from a broader population. The distractor extending the conclusion to all office workers overgeneralizes beyond the study''s volunteers, who were not a random sample of all office workers. The distractor denying causation applies the rule for observational studies, but this is an experiment with random assignment, which does support causal claims. The distractor attributing results to placebo effect is speculation not supported by the study design described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CR70MK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 commuters found that 74 take the bus, 53 take the train, and 19 take both the bus and the train. If a commuter from this survey is chosen at random, what is the probability that the commuter takes the bus or the train?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\dfrac{127}{200}\\)"},{"key":"B","text":"\\(\\dfrac{108}{200}\\)"},{"key":"C","text":"\\(\\dfrac{146}{200}\\)"},{"key":"D","text":"\\(\\dfrac{19}{200}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the inclusion-exclusion principle: P(bus or train) = (74 + 53 - 19)/200 = 108/200. The distractor 127/200 adds 74 + 53 = 127 without subtracting the 19 who take both, double-counting that group. The distractor 146/200 adds all three values (74 + 53 + 19) instead of subtracting the overlap. The distractor 19/200 gives the probability of taking both rather than either.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CVQTPY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $3x + 7y = 42$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 6)$"},{"key":"B","text":"$(6, 0)$"},{"key":"C","text":"$(14, 0)$"},{"key":"D","text":"$(42, 0)$"}]$lyceon_json$::jsonb, 'C', NULL, E'To find the $x$-intercept, set $y = 0$: $3x = 42$, so $x = 14$. The $x$-intercept is $(14, 0)$. The point $(0, 6)$ is the $y$-intercept, found by setting $x = 0$ instead. The point $(6, 0)$ results from dividing $42$ by $7$ (the coefficient of $y$) instead of by $3$ (the coefficient of $x$). The point $(42, 0)$ comes from setting $y = 0$ but not dividing by the coefficient of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZMCI9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The scores of $9$ students on a quiz are: $53, 61, 67, 72, 74, 79, 83, 88, 96$. What is the interquartile range of the scores?', NULL, $lyceon_json$[{"key":"A","text":"$21.5$"},{"key":"B","text":"$43$"},{"key":"C","text":"$74$"},{"key":"D","text":"$22$"}]$lyceon_json$::jsonb, 'A', NULL, E'With $9$ values in order, the median (Q2) is the $5$th value, $74$. The lower quartile Q1 is the median of the four values below the overall median: $53, 61, 67, 72$, so $Q1 = \\frac{61 + 67}{2} = 64$. The upper quartile Q3 is the median of the four values above the overall median: $79, 83, 88, 96$, so $Q3 = \\frac{83 + 88}{2} = 85.5$. The interquartile range is $Q3 - Q1 = 85.5 - 64 = 21.5$. The distractor $43$ is the full range ($96 - 53$), not the interquartile range. The distractor $74$ is the median, not the IQR. The distractor $22$ comes from rounding Q3 to $86$ before subtracting, producing $86 - 64 = 22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F4H31O', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $2x^2 - 11x + 14 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discriminant is $b^2 - 4ac = (-11)^2 - 4(2)(14) = 121 - 112 = 9$. Since $9 > 0$, the equation has $2$ distinct real solutions. The answer $0$ results from incorrectly computing $4ac$ as $4(2)(14) = 128$ instead of $112$, yielding a negative discriminant. The answer $1$ results from an arithmetic slip that produces a discriminant of exactly $0$. The answer $4$ reflects a misconception that a quadratic can have up to $4$ real roots.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GCPAOV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 150 students at a university found that 42% prefer online exams. The margin of error for this estimate is 6 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between 36% and 48% of all students at the university likely prefer online exams."},{"key":"B","text":"Exactly 42% of all students at the university prefer online exams."},{"key":"C","text":"Between 36% and 48% of the 150 students surveyed prefer online exams."},{"key":"D","text":"42% of all universities have students who prefer online exams."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 6 percentage points around a sample proportion of 42% produces a confidence interval of 36% to 48% for the population parameter. The distractor stating exactly 42% ignores the margin of error, treating the sample statistic as the exact population parameter. The distractor limiting the interval to the 150 surveyed students confuses the sample (already measured) with the population being estimated. The distractor about 42% of universities misidentifies the population entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GXWYC7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 10x + 4y - 7 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\sqrt{29}$"},{"key":"C","text":"$6$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'C', NULL, E'Completing the square: $(x^2 - 10x + 25) + (y^2 + 4y + 4) = 7 + 25 + 4 = 36$, so $(x - 5)^2 + (y + 2)^2 = 36$. The radius is $r = \\sqrt{36} = 6$. The value $4$ results from only completing the square for the $y$-terms and taking $\\sqrt{4} = 2$ as a partial answer, or confusing the $y$-coordinate of the center with the radius. The value $\\sqrt{29}$ results from forgetting to move the constant $-7$ to the right side: $25 + 4 = 29$ instead of $7 + 25 + 4 = 36$. The value $36$ results from finding $r^2 = 36$ but reporting $r^2$ instead of $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H0XANX', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the solution $(x, y)$ to the system of equations below?$$\\begin{cases} x + 3y = 19 \\\\ x + y = 9 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$(4, 5)$"},{"key":"B","text":"$(5, 4)$"},{"key":"C","text":"$(14, 5)$"},{"key":"D","text":"$(4, -5)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract the second equation from the first: $(x + 3y) - (x + y) = 19 - 9$, which gives $2y = 10$, so $y = 5$. Substituting into $x + y = 9$: $x = 9 - 5 = 4$. The solution is $(4, 5)$. The pair $(5, 4)$ swaps the $x$- and $y$-values, which fails verification since $5 + 3(4) = 17 \\neq 19$. The pair $(14, 5)$ results from substituting $y = 5$ into the first equation but dropping the coefficient $3$: computing $x + 5 = 19$ instead of $x + 15 = 19$. The pair $(4, -5)$ introduces a sign error on $y$; checking: $4 + (-5) = -1 \\neq 9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H61BKR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands $24$ meters from the base of a building and measures the angle of elevation to the top of the building as $\\alpha$, where $\\tan(\\alpha) = \\frac{15}{8}$. A flagpole stands vertically on top of the building. From the same point, the angle of elevation to the top of the flagpole is $\\beta$, where $\\tan(\\beta) = \\frac{17}{8}$. What is the height of the flagpole, in meters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The height of the building is $24 \\times \\tan(\\alpha) = 24 \\times \\frac{15}{8} = 45$ meters. The height from the ground to the top of the flagpole is $24 \\times \\tan(\\beta) = 24 \\times \\frac{17}{8} = 51$ meters. The height of the flagpole alone is $51 - 45 = 6$ meters. A common error is to compute $\\tan(\\beta) - \\tan(\\alpha) = \\frac{17}{8} - \\frac{15}{8} = \\frac{2}{8} = \\frac{1}{4}$ and then multiply by $24$ to get $6$ (which happens to give the correct answer here) or to forget to multiply by the distance entirely, reporting $\\frac{1}{4}$. Another error is computing each height incorrectly by dividing $24$ by the tangent ratio instead of multiplying.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGILTM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $19$ feet and a width of $14$ feet. What is the area of the garden, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"$33$"},{"key":"B","text":"$66$"},{"key":"C","text":"$252$"},{"key":"D","text":"$266$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $A = 19 \\times 14 = 266$ square feet. The value $33$ is the semi-perimeter ($19 + 14 = 33$), which results from adding the dimensions instead of multiplying. The value $66$ is the perimeter ($2(19 + 14) = 66$), which results from confusing perimeter with area. The value $252$ results from an arithmetic error such as computing $18 \\times 14 = 252$ instead of $19 \\times 14 = 266$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HQWBLY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a flat service fee of $\\$47$ plus $\\$31$ for each hour of work. The total charge, in dollars, is given by the function $C(h) = 31h + 47$, where $h$ is the number of hours worked. What does the number $31$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total charge, in dollars, for $1$ hour of work"},{"key":"B","text":"The rate of change of the total charge, in dollars per hour"},{"key":"C","text":"The flat service fee, in dollars"},{"key":"D","text":"The maximum number of hours the plumber can work"}]$lyceon_json$::jsonb, 'B', NULL, E'In the function $C(h) = 31h + 47$, the coefficient $31$ is the slope, which represents the rate of change of the total charge with respect to hours worked — specifically, the charge increases by $\\$31$ for each additional hour. The total charge for $1$ hour would be $C(1) = 31 + 47 = 78$, not $31$ alone, so that interpretation is incorrect. The flat service fee is represented by the constant $47$, not $31$. The number $31$ is a dollar amount per hour and does not represent any limit on hours worked.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HV9XFK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$ with the right angle at $F$, $DE = 29$ and $DF = 21$. What is $\\tan(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{20}{29}$"},{"key":"B","text":"$\\frac{20}{21}$"},{"key":"C","text":"$\\frac{21}{20}$"},{"key":"D","text":"$\\frac{21}{29}$"}]$lyceon_json$::jsonb, 'B', NULL, E'First find $EF$ using the Pythagorean theorem: $EF = \\sqrt{DE^2 - DF^2} = \\sqrt{841 - 441} = \\sqrt{400} = 20$. Then $\\tan(D) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{EF}{DF} = \\frac{20}{21}$. The ratio $\\frac{20}{29}$ is $\\sin(D)$ (opposite over hypotenuse), not tangent. The ratio $\\frac{21}{20}$ is $\\cot(D)$ (the reciprocal of tangent), which results from swapping opposite and adjacent. The ratio $\\frac{21}{29}$ is $\\cos(D)$ (adjacent over hypotenuse), not tangent.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I75TFE', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{49p^2 - 25q^2}{7p + 5q}$?', NULL, $lyceon_json$[{"key":"A","text":"$7p + 5q$"},{"key":"B","text":"$7p - 5q$"},{"key":"C","text":"$7p^2 - 5q^2$"},{"key":"D","text":"$42p - 30q$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $49p^2 - 25q^2$ is a difference of squares: $(7p)^2 - (5q)^2 = (7p + 5q)(7p - 5q)$. Dividing by $7p + 5q$ cancels one factor, leaving $7p - 5q$. The expression $7p + 5q$ results from canceling the wrong factor, ignoring the sign difference in the factorization. The expression $7p^2 - 5q^2$ incorrectly strips only the leading coefficient from each squared term without proper factoring. The expression $42p - 30q$ comes from multiplying $7p - 5q$ by $6$, an extraneous arithmetic step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IJ6EQT', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $\\ell$ passes through the point $(8, 1)$ and is perpendicular to the line $4x - 3y = 21$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$\\frac{35}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite $4x - 3y = 21$ in slope-intercept form: $y = \\frac{4}{3}x - 7$, so the slope is $\\frac{4}{3}$. The perpendicular slope is $-\\frac{3}{4}$. Using point-slope form with $(8, 1)$: $y - 1 = -\\frac{3}{4}(x - 8) = -\\frac{3}{4}x + 6$, giving $y = -\\frac{3}{4}x + 7$. The $y$-intercept is $7$. The distractor $-7$ comes from a sign error, confusing the $y$-intercept of line $\\ell$ with the $y$-intercept of the original line. The distractor $-5$ arises from using the reciprocal slope $\\frac{3}{4}$ without negating: $y - 1 = \\frac{3}{4}(x - 8) = \\frac{3}{4}x - 6$, giving $y$-intercept $-5$. The distractor $\\frac{35}{3}$ results from negating the original slope to $-\\frac{4}{3}$ without taking the reciprocal: $y - 1 = -\\frac{4}{3}(x - 8) = -\\frac{4}{3}x + \\frac{32}{3}$, giving $y$-intercept $\\frac{35}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IWKG59', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations below has infinitely many solutions. What is the value of $k$?$$\\begin{cases} 6x - 9y = 21 \\\\ -2x + 3y = k \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$-21$"}]$lyceon_json$::jsonb, 'B', NULL, E'For the system to have infinitely many solutions, the two equations must be scalar multiples of each other. Multiplying the second equation by $-3$: $-3(-2x + 3y) = -3k$, yielding $6x - 9y = -3k$. For this to equal the first equation, $-3k = 21$, so $k = -7$. The value $7$ results from a sign error, solving $3k = 21$ instead of $-3k = 21$. The value $-3$ comes from confusing the scalar multiplier itself ($-3$) with the value of $k$. The value $-21$ arises from assuming the constants of the two equations must simply be negatives of each other without accounting for the coefficient ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWJPCP', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $k$ does the equation $$k(3x - 7) = 12x + 5$$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{5}{7}$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expand the left side: $3kx - 7k = 12x + 5$. A linear equation has no solution when the coefficients of $x$ are equal but the constant terms differ. Setting $3k = 12$ gives $k = 4$. With $k = 4$, the constant on the left is $-7(4) = -28$, which is not equal to $5$, confirming no solution exists. The distractor $-\\frac{5}{7}$ arises from setting the constants equal ($-7k = 5$) instead of the coefficients, which is the condition for a different scenario. The distractor $-4$ comes from a sign error when solving $3k = 12$. The distractor $12$ results from identifying the coefficient of $x$ on the right side but failing to divide by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K0G0FX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h$ is defined by $h(x) = -2x^3 + 9x^2 - 12x + 5$. At which value of $x$ does $h$ attain a local maximum?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$2$"},{"key":"C","text":"$\\frac{3}{2}$"},{"key":"D","text":"$\\frac{9}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Taking the derivative: $h''(x) = -6x^2 + 18x - 12 = -6(x^2 - 3x + 2) = -6(x - 1)(x - 2)$. Setting $h''(x) = 0$ gives critical points at $x = 1$ and $x = 2$. Analyzing the sign of $h''$: for $x < 1$, both factors $(x-1)$ and $(x-2)$ are negative, so their product is positive, and multiplied by $-6$ gives $h''(x) < 0$; for $1 < x < 2$, $(x-1) > 0$ and $(x-2) < 0$, so the product is negative, and $h''(x) > 0$; for $x > 2$, both factors are positive, so the product is positive, and $h''(x) < 0$. Since $h''$ changes from positive to negative at $x = 2$, this is a local maximum. At $x = 1$, $h''$ changes from negative to positive, so that is a local minimum. The value $x = 1$ is selected by students who find both critical points but confuse which is the maximum and which is the minimum. The value $\\frac{3}{2}$ arises from averaging the two critical points. The value $\\frac{9}{4}$ comes from incorrectly applying the vertex formula $-\\frac{b}{2a}$ to the cubic''s original coefficients $a = -2$ and $b = 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K9S86B', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'$$2(3x + 7) - 5 = 4x + 23$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LLU3ZH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One pair of co-interior (same-side interior) angles are $(3x + 11)^\\circ$ and $(5x - 7)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$16$"},{"key":"C","text":"$22$"},{"key":"D","text":"$44$"}]$lyceon_json$::jsonb, 'C', NULL, E'Co-interior angles formed by parallel lines and a transversal are supplementary, so they sum to $180^\\circ$: $(3x + 11) + (5x - 7) = 180$. Simplifying gives $8x + 4 = 180$, so $8x = 176$ and $x = 22$. The value $9$ results from incorrectly setting the two angle expressions equal rather than summing them to $180^\\circ$: $3x + 11 = 5x - 7$ gives $x = 9$. The value $16$ results from an arithmetic slip such as computing $180 - 4 = 168$ and then $168 \\div 8 = 21$ with a further rounding error. The value $44$ results from dividing $176$ by $4$ instead of $8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LX7VHD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling firm surveys a random sample of 900 residents in a city and finds that 61% favor expanding the public transit system, with a margin of error of 3.2 percentage points at a 95% confidence level. A journalist reports that this result proves at least 55% of all city residents favor the expansion. Which of the following statements best evaluates the journalist''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is supported because the entire 95% confidence interval (57.8% to 64.2%) is above 55%."},{"key":"B","text":"The claim is not supported because the sample proportion could differ from the population proportion."},{"key":"C","text":"The claim is supported because 61% is greater than 55%."},{"key":"D","text":"The claim is not supported because 55% does not fall within the confidence interval."}]$lyceon_json$::jsonb, 'A', NULL, E'The 95% confidence interval is 61% plus or minus 3.2%, which gives 57.8% to 64.2%. Since the entire interval lies above 55%, there is strong statistical evidence that the true population proportion exceeds 55%, supporting the journalist''s claim. The distractor arguing the claim is unsupported merely because sample and population values can differ is too vague and ignores that the confidence interval quantifies that uncertainty. The distractor citing only that 61% is greater than 55% uses the point estimate without accounting for the margin of error, which is incomplete reasoning. The distractor stating the claim fails because 55% is outside the interval misinterprets the logic: the relevant question is whether the interval is entirely above 55%, not whether 55% is inside it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJMJGU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A solid is formed by removing a cone from a cylinder. The cylinder and the cone share the same circular base with radius $8$ and the same height of $15$. What is the volume of the remaining solid? (If the volume is $k\\pi$, enter the value of $k$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '640', ARRAY['640'], E'The volume of the cylinder is $V_{\\text{cyl}} = \\pi r^2 h = \\pi(8)^2(15) = 960\\pi$. The volume of the cone is $V_{\\text{cone}} = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(8)^2(15) = 320\\pi$. The remaining volume is $960\\pi - 320\\pi = 640\\pi$, so $k = 640$. A common error is forgetting the $\\frac{1}{3}$ factor for the cone, computing the cone volume as $960\\pi$ and getting a remaining volume of $0$. Another error is subtracting the radius or height instead of computing volumes: for example, computing $\\pi(8)^2(15 - 5) = 640\\pi$ by subtracting an arbitrary value from the height. A third error is using $\\frac{2}{3}$ of the cylinder volume directly ($\\frac{2}{3} \\times 960\\pi = 640\\pi$), which happens to be correct since removing a cone with the same base and height leaves $\\frac{2}{3}$ of the cylinder volume.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NREXXR', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A craft fair vendor has $\\$78$ to spend on supplies. Each set of beads costs $\\$9$, and the vendor has already spent $\\$15$ on string. Which inequality can be used to determine $b$, the maximum number of bead sets the vendor can still purchase?', NULL, $lyceon_json$[{"key":"A","text":"$9b + 15 \\leq 78$"},{"key":"B","text":"$9b - 15 \\leq 78$"},{"key":"C","text":"$9b + 15 \\geq 78$"},{"key":"D","text":"$9b \\leq 78$"}]$lyceon_json$::jsonb, 'A', NULL, E'The vendor has already spent $\\$15$ and each bead set costs $\\$9$, so the total spending is $15 + 9b$. Since the vendor cannot exceed $\\$78$, the correct inequality is $9b + 15 \\leq 78$. The option $9b - 15 \\leq 78$ incorrectly subtracts the amount already spent instead of adding it to the total. The option $9b + 15 \\geq 78$ reverses the inequality direction, implying the vendor must spend at least $\\$78$ rather than at most. The option $9b \\leq 78$ omits the $\\$15$ already spent entirely, as though that cost does not count toward the budget.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NXIGJN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town had a population of $5{,}000$ in $2022$. The population increased by $8\\%$ from $2022$ to $2023$, and then decreased by $5\\%$ from $2023$ to $2024$. What was the population in $2024$?', NULL, $lyceon_json$[{"key":"A","text":"$5{,}130$"},{"key":"B","text":"$5{,}150$"},{"key":"C","text":"$5{,}000$"},{"key":"D","text":"$5{,}670$"}]$lyceon_json$::jsonb, 'A', NULL, E'In $2023$, the population was $5{,}000 \\times 1.08 = 5{,}400$. In $2024$, the population was $5{,}400 \\times 0.95 = 5{,}130$. The distractor $5{,}150$ comes from incorrectly combining the percentages as a net $3\\%$ increase applied to the original ($5{,}000 \\times 1.03 = 5{,}150$), which ignores that the $5\\%$ decrease applies to the already-increased value. The distractor $5{,}000$ assumes the increase and decrease cancel each other out. The distractor $5{,}670$ comes from applying both as increases ($5{,}000 \\times 1.08 \\times 1.05 = 5{,}670$) instead of an increase followed by a decrease.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NY03WS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(3, -2)$ and $(9, 16)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-11', ARRAY['-11'], E'First, find the slope: $m = \\frac{16 - (-2)}{9 - 3} = \\frac{18}{6} = 3$. Using point-slope form with $(3, -2)$: $y - (-2) = 3(x - 3)$, which gives $y + 2 = 3x - 9$, so $y = 3x - 11$. The $y$-intercept is $-11$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OK5SH2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The price of a commodity increased by $25\\%$ in the first year. In the second year, the price decreased by $p$ percent from its value at the end of the first year. If the price at the end of the second year was $5\\%$ greater than the original price, what is the value of $p$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$16$"},{"key":"C","text":"$20$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the original price be $100$. After a $25\\%$ increase, the price is $125$. After a $p\\%$ decrease, the price is $125 \\times (1 - \\frac{p}{100})$, which must equal $105$ (a $5\\%$ increase over the original). So $125(1 - \\frac{p}{100}) = 105$, giving $1 - \\frac{p}{100} = \\frac{105}{125} = 0.84$, and $p = 16$. The distractor $20$ results from naively subtracting the net percentage from the increase ($25 - 5 = 20$), which ignores that the decrease applies to the already-increased price. The distractor $25$ assumes the decrease must equal the original increase percentage to return near the original value. The distractor $12$ comes from an arithmetic error in dividing $105$ by $125$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OMWSKS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $$y = x^2 - 4x + 7$$ $$y = 2x - 1$$ has two solutions $(x_1, y_1)$ and $(x_2, y_2)$. What is the value of $x_1 + x_2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Setting the equations equal: $x^2 - 4x + 7 = 2x - 1$. Rearranging: $x^2 - 6x + 8 = 0$. Factoring: $(x - 2)(x - 4) = 0$, so $x_1 = 2$ and $x_2 = 4$. Therefore $x_1 + x_2 = 2 + 4 = 6$. Alternatively, by Vieta''s formulas, the sum of the roots of $x^2 - 6x + 8 = 0$ is $-\\frac{-6}{1} = 6$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZKTJU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A pair of headphones originally priced at $\\$160$ is on sale for $25\\%$ off. What is the sale price of the headphones?', NULL, $lyceon_json$[{"key":"A","text":"$\\$40$"},{"key":"B","text":"$\\$120$"},{"key":"C","text":"$\\$135$"},{"key":"D","text":"$\\$140$"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is $25\\%$ of $\\$160$: $0.25 \\times 160 = \\$40$. The sale price is $\\$160 - \\$40 = \\$120$. The distractor $\\$40$ gives the discount amount rather than the sale price. The distractor $\\$135$ results from subtracting $25$ directly instead of computing $25\\%$. The distractor $\\$140$ comes from subtracting $20$ (confusing $25\\%$ with a $\\$20$ discount).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PB9RNB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle with center $O$ has a radius of $15$. Points $A$ and $B$ lie on the circle such that the central angle $AOB$ measures $\\frac{2\\pi}{5}$ radians. What is the area of the minor sector $AOB$? (If the area is $k\\pi$, enter the value of $k$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '45', ARRAY['45'], E'The area of a sector is $A = \\frac{1}{2}r^2\\theta$. With $r = 15$ and $\\theta = \\frac{2\\pi}{5}$: $A = \\frac{1}{2}(15)^2 \\cdot \\frac{2\\pi}{5} = \\frac{1}{2}(225) \\cdot \\frac{2\\pi}{5} = \\frac{450\\pi}{10} = 45\\pi$. So $k = 45$. A common error is using the arc-length formula $s = r\\theta = 15 \\cdot \\frac{2\\pi}{5} = 6\\pi$ instead of the sector area formula. Another error is forgetting the $\\frac{1}{2}$ factor, computing $r^2\\theta = 225 \\cdot \\frac{2\\pi}{5} = 90\\pi$, which gives $k = 90$. A third error is using the full circle area $225\\pi$ and dividing by $5$ instead of multiplying by $\\frac{2}{5}$, yielding $45\\pi$ (which happens to be correct only because $\\frac{\\theta}{2\\pi} = \\frac{1}{5}$... confirming the answer through the ratio method as well: $\\frac{2\\pi/5}{2\\pi} \\times 225\\pi = \\frac{1}{5} \\times 225\\pi = 45\\pi$).', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PILPV4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A dataset consists of $10$ values with a mean of $46$ and a standard deviation of $8$. If each value in the dataset is multiplied by $3$ and then $7$ is added to the result, what is the standard deviation of the new dataset?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$31$"},{"key":"C","text":"$8$"},{"key":"D","text":"$145$"}]$lyceon_json$::jsonb, 'A', NULL, E'When each value is transformed by $y = 3x + 7$, the standard deviation is affected only by the multiplicative factor, not by the additive constant. The new standard deviation is $3 \\times 8 = 24$. The distractor $31$ incorrectly applies both the multiplication and addition to the standard deviation ($3 \\times 8 + 7 = 31$), but adding a constant shifts all values equally and does not change spread. The distractor $8$ assumes the standard deviation is unchanged by any transformation, ignoring the effect of multiplication. The distractor $145$ is the new mean ($46 \\times 3 + 7 = 145$), not the standard deviation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S7Q0RJ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A carpenter builds tables and chairs. Each table requires $7$ hours of labor and each chair requires $3$ hours. The carpenter works at most $41$ hours per week and must build at least $3$ tables per week. What is the maximum number of chairs the carpenter can build in one week? (Assume only whole tables and chairs can be built.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Let $t$ represent the number of tables and $c$ the number of chairs. The constraints are $7t + 3c \\leq 41$, $t \\geq 3$, and $c \\geq 0$, with $t$ and $c$ as non-negative integers. To maximize $c$, minimize $t$ by setting $t = 3$. Substituting: $7(3) + 3c \\leq 41$, so $21 + 3c \\leq 41$, giving $3c \\leq 20$, hence $c \\leq 6.\\overline{6}$. Since only whole chairs can be built, the maximum is $c = 6$. A student who uses $t = 3$ but rounds $6.\\overline{6}$ up to $7$ violates the hour constraint since $21 + 21 = 42 > 41$. A student who forgets the constraint $t \\geq 3$ and sets $t = 0$ would get $3c \\leq 41$, yielding $c = 13$, which ignores the table requirement.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TA7YH9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A school district randomly selects 300 eighth-graders from all eighth-graders in the district and randomly assigns them to two groups: one group uses a new math tutoring app for one semester, and the other group receives no additional resources. At the end of the semester, the group using the app scores significantly higher on a standardized math test. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The tutoring app caused higher test scores, but only for the students in the study."},{"key":"B","text":"The tutoring app caused higher test scores, and this result can be generalized to all eighth-graders in the district."},{"key":"C","text":"There is an association between using the app and higher scores, but no causal conclusion can be drawn."},{"key":"D","text":"The tutoring app will improve test scores for eighth-graders in any school district."}]$lyceon_json$::jsonb, 'B', NULL, E'The study uses both random selection (from all eighth-graders in the district) and random assignment (to treatment and control groups). Random assignment supports a causal conclusion, and random selection supports generalizing to the population from which the sample was drawn, which is all eighth-graders in the district. The distractor limiting the conclusion to only the study participants ignores that random selection from the district population allows generalization to that population. The distractor denying any causal conclusion incorrectly applies the observational-study limitation to a randomized experiment. The distractor extending to any school district overgeneralizes beyond the population from which the random sample was drawn.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UI6DF4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A dataset contains the values $13, 17, 19, 23, 29$. What is the median of the dataset?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$20.2$"},{"key":"C","text":"$21$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'A', NULL, E'The dataset has $5$ values already in ascending order. The median is the middle (third) value, which is $19$. The distractor $20.2$ is the mean of the dataset ($(13 + 17 + 19 + 23 + 29) \\div 5 = 101 \\div 5 = 20.2$), not the median. The distractor $21$ is the midrange ($(13 + 29) \\div 2 = 21$), which is a different measure. The distractor $23$ comes from selecting the fourth value instead of the third, miscounting the middle position.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2USARMC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $16$ and the hypotenuse has length $65$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$57$"},{"key":"C","text":"$63$"},{"key":"D","text":"$81$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Pythagorean theorem, $16^2 + b^2 = 65^2$, so $256 + b^2 = 4225$, giving $b^2 = 3969$ and $b = 63$. The value $49$ comes from subtracting the leg from the hypotenuse ($65 - 16 = 49$) instead of using the Pythagorean theorem. The value $57$ results from an arithmetic error when computing $\\sqrt{3969}$, such as approximating incorrectly. The value $81$ results from adding the squares ($256 + 4225 = 4481$) and taking $\\sqrt{4481} \\approx 81$, which incorrectly adds instead of subtracts.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UY4XL7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a set of data is given by $y = 3.7x + 14.2$. According to the model, what is the predicted value of $y$ when $x = 11$?', NULL, $lyceon_json$[{"key":"A","text":"$40.7$"},{"key":"B","text":"$54.9$"},{"key":"C","text":"$28.9$"},{"key":"D","text":"$51.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 11$ into the equation: $y = 3.7(11) + 14.2 = 40.7 + 14.2 = 54.9$. The distractor $40.7$ results from computing $3.7 \\times 11$ but forgetting to add the $y$-intercept of $14.2$. The distractor $28.9$ comes from adding all three numbers ($3.7 + 11 + 14.2 = 28.9$) instead of multiplying. The distractor $51.2$ results from using $x = 10$ instead of $x = 11$, giving $3.7(10) + 14.2 = 51.2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W3U7IP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{8x^3 - 27}{2x - 3} = ax^2 + bx + c$ for all values of $x$ where the expression is defined, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$19$"},{"key":"C","text":"$7$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator $8x^3 - 27 = (2x)^3 - 3^3$ is a difference of cubes. Using the identity $a^3 - b^3 = (a - b)(a^2 + ab + b^2)$ with $a = 2x$ and $b = 3$ gives $(2x - 3)(4x^2 + 6x + 9)$. Dividing by $2x - 3$ yields $4x^2 + 6x + 9$, so $a = 4$, $b = 6$, $c = 9$, and $a + b + c = 19$. The value $13$ comes from omitting the middle term $6x$, computing $4 + 0 + 9 = 13$. The value $7$ arises from a sign error in the middle term, yielding $4x^2 - 6x + 9$ and getting $4 - 6 + 9 = 7$. The value $27$ mistakes the cube $3^3 = 27$ for the answer, neglecting the polynomial division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WAGFPK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory assembles $29$ circuit boards in $5$ hours. At this constant rate, how many circuit boards does the factory assemble in $15$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$87$"},{"key":"C","text":"$97$"},{"key":"D","text":"$145$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{29}{5} = 5.8$ circuit boards per hour. In $15$ hours, the factory assembles $5.8 \\times 15 = 87$ circuit boards. The distractor $72$ results from incorrectly computing $29 \\times \\frac{15}{6}$. The distractor $97$ comes from adding $29 + 15 \\times \\frac{29}{6.5}$ through a rounding error. The distractor $145$ results from multiplying $29 \\times 5$ instead of dividing first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YMWEKC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collected data on years of experience, $x$, and annual salary in thousands of dollars, $y$, for $50$ employees. The line of best fit is $y = 2.9x + 31.7$, and the correlation coefficient is $r = 0.87$. An employee with $14$ years of experience earns an annual salary of $\\$73{,}400$. What is the residual for this employee, in thousands of dollars?', NULL, $lyceon_json$[{"key":"A","text":"$-1.1$"},{"key":"B","text":"$1.1$"},{"key":"C","text":"$72.3$"},{"key":"D","text":"$0.87$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted salary for $x = 14$ is $y = 2.9(14) + 31.7 = 40.6 + 31.7 = 72.3$ thousand dollars. The actual salary is $73.4$ thousand dollars ($\\$73{,}400$). The residual is the actual value minus the predicted value: $73.4 - 72.3 = 1.1$ thousand dollars. The distractor $-1.1$ reverses the residual formula by computing predicted minus actual instead of actual minus predicted. The distractor $72.3$ is the predicted value itself rather than the residual. The distractor $0.87$ is the correlation coefficient, which is unrelated to the residual for a single data point.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZCSGWG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^3 \\cdot 3x^4$?', NULL, $lyceon_json$[{"key":"A","text":"$21x^{7}$"},{"key":"B","text":"$21x^{12}$"},{"key":"C","text":"$10x^{7}$"},{"key":"D","text":"$10x^{12}$"}]$lyceon_json$::jsonb, 'A', NULL, E'When multiplying monomials, multiply the coefficients and add the exponents: $7 \\cdot 3 = 21$ and $x^3 \\cdot x^4 = x^{3+4} = x^7$, giving $21x^7$. The expression $21x^{12}$ results from multiplying the exponents instead of adding them ($3 \\times 4 = 12$). The expression $10x^7$ results from adding the coefficients instead of multiplying them ($7 + 3 = 10$). The expression $10x^{12}$ combines both errors: adding coefficients and multiplying exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW200VXWI', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the approach described in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20CJHBQ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economist Renata Vlasic has studied pricing patterns in independent bookstores across eleven mid-sized European cities. She found that stores located within 200 meters of a university campus charged, on average, 7 percent less for new hardcover titles than stores in other commercial districts of the same city. Vlasic notes that the campus-adjacent stores did not receive larger wholesale discounts from publishers; their cost structures were essentially identical to those of other independent bookstores. However, she also found that campus-adjacent stores sold approximately 40 percent more units per month than their counterparts elsewhere. Vlasic concludes that the lower prices at campus-adjacent stores are best explained by ________', $lyceon_json$[{"key":"A","text":"their ability to offset thinner per-unit margins with substantially higher sales volume."},{"key":"B","text":"undisclosed agreements with universities that subsidize a portion of the stores' operating costs."},{"key":"C","text":"a preference among university students for purchasing used rather than new copies of books."},{"key":"D","text":"reduced competition from online retailers in areas immediately surrounding university campuses."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that campus-adjacent stores charge less despite identical costs and sell 40 percent more units. The logical conclusion connecting these facts is that higher volume compensates for lower per-unit margins, making the pricing strategy viable. The claim about university subsidies introduces an explanation with no support in the passage; Vlasic''s data addresses wholesale costs and sales volume, not external subsidies. The claim about used-book preferences is irrelevant because the study specifically tracks new hardcover pricing. The claim about reduced online competition near campuses introduces a factor not mentioned or implied by the data Vlasic collected.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21AS98V', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes data from the study that would support Okonkwo''s claim?', E'Sociologist Adaeze Okonkwo has argued that multilingual households in urban Nigeria experience lower rates of intergenerational language loss than sociolinguistic models would predict. Most models assume that when a dominant language — in this case, English — pervades education, media, and commerce, heritage languages recede within two to three generations. Okonkwo contends that in cities such as Lagos and Port Harcourt, the social prestige associated with ethnic identity creates a countervailing force that sustains heritage language use even among younger, highly educated residents. To test this claim, Okonkwo surveyed 1,370 households across four Nigerian cities, tracking language use patterns among three generations within each household.', $lyceon_json$[{"key":"A","text":"Data showing that third-generation residents in multilingual Lagos households report using their heritage language daily at rates significantly above the threshold predicted by standard language-shift models."},{"key":"B","text":"Data showing that English proficiency among first-generation immigrants to Lagos has increased substantially compared to earlier decades."},{"key":"C","text":"Data showing that heritage language instruction is offered in most public schools across the four surveyed cities."},{"key":"D","text":"Data showing that households in rural Nigerian communities maintain heritage languages at higher rates than urban households do."}]$lyceon_json$::jsonb, 'A', NULL, E'Okonkwo claims that urban multilingual households retain heritage languages at higher rates than standard models predict. Data showing third-generation urban residents using heritage languages above model-predicted thresholds would directly confirm this claim. Data about rising English proficiency among first-generation immigrants addresses a different phenomenon — acquisition of the dominant language — and says nothing about heritage language retention across generations. Data about school-based heritage language instruction identifies a possible mechanism but does not demonstrate the outcome Okonkwo claims (lower-than-predicted language loss in households). Data about rural communities maintaining higher rates than urban ones would actually undercut Okonkwo''s specific argument about urban resilience.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HUZQU', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the ceramic artist Kwame Asante began exhibiting in Accra galleries in 2011, critics praised his vessels for their geometric precision but faulted them for lacking emotional resonance. Stung by this assessment, Asante spent two years apprenticing with Ewe potters in the Volta Region, learning techniques for embedding symbolic motifs into clay surfaces. His subsequent 2014 collection retained the mathematical rigor of his earlier work while incorporating ancestral iconography that reviewers described as deeply evocative.', $lyceon_json$[{"key":"A","text":"It presents a problem an artist faced, describes the steps he took to address it, and then notes the outcome of those efforts."},{"key":"B","text":"It compares two competing artistic traditions and argues that one is superior to the other."},{"key":"C","text":"It introduces a critical theory about ceramics and then provides examples that challenge that theory."},{"key":"D","text":"It traces the commercial success of an artist and attributes that success to favorable market conditions."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a clear three-part arc: first, it identifies a criticism of Asante''s early work (lacking emotional resonance); second, it describes his response (apprenticing with Ewe potters to learn symbolic techniques); third, it reports the result (a new collection that combined precision with evocative iconography). The option about comparing two competing traditions and declaring one superior mischaracterizes the passage, which shows Asante integrating elements from both geometric precision and Ewe symbolic motifs rather than ranking one above the other. The option about introducing and then challenging a critical theory is wrong because the passage does not present any abstract theoretical framework—it narrates one artist''s personal development. The option about tracing commercial success is wrong because the passage discusses critical reception and artistic growth, never mentioning sales, prices, or market conditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27C021W', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In her 2019 monograph on Renaissance cartography, historian Celeste Moreira examined portolan charts produced in Lisbon between 1471 and 1503. Moreira found that the cartographers who created these charts _______ a standardized system of wind roses that differed markedly from the conventions used by their Genoese counterparts.', $lyceon_json$[{"key":"A","text":"had adopted"},{"key":"B","text":"have adopted"},{"key":"C","text":"will adopt"},{"key":"D","text":"adopts"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes a past-tense narrative frame: Moreira ''examined'' and ''found.'' The cartographers'' adoption of the system occurred before Moreira''s finding, making the past perfect (''had adopted'') the correct tense to indicate an action completed prior to another past action. ''Have adopted'' is present perfect, which implies a connection to the present and clashes with the past-tense narrative. ''Will adopt'' is future tense, which contradicts the historical context. ''Adopts'' is present tense singular and fails both in tense and in number agreement with the plural subject ''cartographers.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27UMYDP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The fruit fly Drosophila melanogaster completes its entire life cycle in roughly twelve days at 25 degrees Celsius. This rapid generational turnover allows geneticists to observe the effects of mutations across dozens of generations within a single academic semester. __As a result, Drosophila has become the organism of choice for introductory genetics laboratories worldwide.__', $lyceon_json$[{"key":"A","text":"It states a consequence of the characteristic described earlier in the text."},{"key":"B","text":"It introduces a new hypothesis that contradicts the preceding claim."},{"key":"C","text":"It provides a specific numerical measurement to support a generalization."},{"key":"D","text":"It defines a technical term used in the previous sentence."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence begins with "As a result," signaling that it presents an outcome or consequence. The preceding sentences establish that Drosophila has a rapid life cycle and that this speed benefits genetic research; the underlined sentence then draws the conclusion that this advantage has made Drosophila the standard laboratory organism. The option stating it introduces a contradictory hypothesis is wrong because the underlined sentence agrees with and follows from the prior information rather than challenging it. The option about providing a numerical measurement is wrong because the underlined sentence contains no numbers—the numerical detail (twelve days, 25 degrees) appears earlier in the passage. The option about defining a technical term is wrong because no term is being defined in the underlined sentence; it instead describes a practical outcome.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BZX1C9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The research team at the Sverdrup Polar Institute recently completed a comprehensive survey of lichen diversity across eleven remote Arctic islands. The evidence from their fieldwork _______ that at least three previously undocumented species thrive in microhabitats sheltered by north-facing granite outcrops.', $lyceon_json$[{"key":"A","text":"suggest"},{"key":"B","text":"suggests"},{"key":"C","text":"have suggested"},{"key":"D","text":"are suggesting"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is ''evidence,'' which is a singular uncountable noun. A singular subject requires a singular verb form. The option ''suggests'' is the third-person singular present tense form and agrees with ''evidence.'' The bare form ''suggest'' is plural and does not agree with the singular subject. ''Have suggested'' uses a plural auxiliary (''have'' rather than ''has'') and therefore also fails to agree. ''Are suggesting'' likewise uses a plural auxiliary and does not agree with the singular subject.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C1V7SY', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In 1927, the entomologist Miriam Rothschild began cataloging the flea specimens her father, Charles Rothschild, had amassed over decades of fieldwork. The collection, numbering roughly 260,000 individual specimens representing over 900 species, was the largest of its kind in the world. Miriam Rothschild spent nearly thirty years organizing and describing the collection before donating it to the Natural History Museum in London. Her meticulous work on fleas earned her recognition as one of the foremost parasitologists of the twentieth century, despite the fact that she held no formal university degree.', $lyceon_json$[{"key":"A","text":"Miriam Rothschild's sustained effort to document an enormous flea collection established her as a leading figure in parasitology."},{"key":"B","text":"Charles Rothschild's decades of fieldwork produced a flea collection that was unmatched in size by any other private or institutional holding."},{"key":"C","text":"The Natural History Museum in London acquired a significant entomological collection through a donation in the mid-twentieth century."},{"key":"D","text":"Researchers who lack formal university degrees have historically been excluded from recognition in the biological sciences."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Miriam Rothschild''s decades-long project of cataloging her father''s flea collection and the professional recognition she gained from it, making the option about her sustained documentation work and resulting reputation the best statement of the main idea. The option focusing on Charles Rothschild''s fieldwork misidentifies the subject of the passage; while his collection is mentioned, the text is about Miriam''s work on it, not about how he assembled it. The option about the Natural History Museum''s acquisition captures only a secondary detail (the donation) rather than the passage''s central point. The option claiming that researchers without degrees have been excluded contradicts the passage, which states Rothschild earned recognition despite lacking a degree, not that she was excluded.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C7MDB7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand tree Corynocarpus laevigatus, commonly known as karaka, contains a toxic alkaloid called karakin in its seed. Historically, Māori communities developed an elaborate multi-day process of roasting and soaking the seeds to neutralize the toxin before consumption. Archaeological evidence shows that karaka trees were deliberately planted far outside their natural coastal range, appearing at inland settlement sites dating to the fourteenth century. This distribution pattern suggests that ________', $lyceon_json$[{"key":"A","text":"Māori communities valued karaka as a food source sufficiently to cultivate it in new environments despite the labor required to make it safe for consumption."},{"key":"B","text":"the karakin toxin in karaka seeds became less potent when the trees were grown in inland soils rather than coastal soils."},{"key":"C","text":"karaka trees were primarily cultivated for their timber rather than their fruit at inland settlement sites."},{"key":"D","text":"the detoxification process used by Māori communities was discovered accidentally during attempts to use karaka wood for construction."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that karaka seeds are toxic, that Māori developed a complex detoxification process, and that karaka trees were deliberately planted at inland sites beyond their natural range. The most logical inference linking these facts is that communities considered karaka valuable enough as food to transplant it despite the effort involved. The claim about reduced toxin potency in inland soils introduces a biological mechanism not suggested anywhere in the passage. The claim about timber cultivation contradicts the passage''s focus on the fruit and its preparation for eating. The claim about accidental discovery during construction invents a narrative with no basis in the information provided.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EICXJC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Yuki Harada has been studying the migration patterns of painted lady butterflies across the Sahara. Her team tracked individual butterflies using lightweight radar transponders and discovered that the insects, despite flying at altitudes exceeding 1,500 meters, _______ remarkably consistent headings by adjusting their flight angles relative to prevailing crosswinds.', $lyceon_json$[{"key":"A","text":"maintains"},{"key":"B","text":"maintaining"},{"key":"C","text":"maintain"},{"key":"D","text":"having maintained"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the verb is ''the insects,'' a plural noun. The intervening parenthetical clause ''despite flying at altitudes exceeding 1,500 meters'' is set off by commas and does not change the subject or the need for a finite verb. The plural present-tense form ''maintain'' agrees with ''the insects'' and provides the finite verb the clause requires. ''Maintains'' is singular and does not agree with the plural subject. ''Maintaining'' is a participle, not a finite verb, and would leave the clause without a main verb, creating a sentence fragment. ''Having maintained'' is also a participial phrase and similarly fails to provide a finite verb for the independent clause.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F54EX2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Petra Lindqvist has spent seventeen years cataloging bioluminescent organisms in the Barents _______ her findings have reshaped scientific understanding of light-producing bacteria in Arctic waters.', $lyceon_json$[{"key":"A","text":"Sea, and"},{"key":"B","text":"Sea and,"},{"key":"C","text":"Sea, and,"},{"key":"D","text":"Sea and"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses are joined here: one about Lindqvist''s cataloging work and one about the impact of her findings. When joining two independent clauses with the coordinating conjunction ''and,'' a comma must precede the conjunction. The option placing a comma before ''and'' with no additional errant punctuation is the only choice that conforms to Standard English. Placing the comma after the conjunction, adding commas on both sides of the conjunction, or omitting the comma entirely all violate standard conventions for joining independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F5PAKF', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the hypothesis advanced in the text?', E'Paleobotanist Luís Ferreira has proposed that the high density of fossilized angiosperm pollen found in Late Cretaceous sediments from the Antarctic Peninsula indicates that the region supported a diverse temperate rainforest during that period. Ferreira argues that the pollen assemblages — which include taxa closely related to modern southern beeches, tree ferns, and flowering shrubs — could only have been produced by plants growing locally, since the large, ornamented pollen grains of these species are too heavy for long-distance atmospheric transport. He further notes that the sediment layers contain leaf impressions and root traces consistent with in situ forest growth.', $lyceon_json$[{"key":"A","text":"Experiments demonstrate that pollen grains of the size and ornamentation found in the Antarctic sediments can be carried over 3,000 kilometers by sustained polar wind currents before settling."},{"key":"B","text":"Fossilized pollen from coniferous species, which are associated with cooler climates, is also present in the same Antarctic sediment layers."},{"key":"C","text":"Late Cretaceous ocean temperatures near the Antarctic Peninsula were warmer than those observed in the region today."},{"key":"D","text":"Modern southern beech species produce pollen grains that are morphologically similar to those found in the Antarctic fossil record."}]$lyceon_json$::jsonb, 'A', NULL, E'Ferreira''s hypothesis rests on two supports: the pollen assemblages and the claim that the heavy, ornamented pollen could not have traveled long distances. A finding that such pollen can in fact be carried thousands of kilometers by polar winds directly attacks this key premise, undermining the conclusion that the plants must have grown locally. The presence of coniferous pollen in the same layers does not undermine the hypothesis; temperate rainforests can include conifers alongside angiosperms, so this finding is compatible with Ferreira''s claim. Warmer ocean temperatures near the Antarctic Peninsula would, if anything, make a temperate rainforest more plausible, not less. The morphological similarity between modern southern beech pollen and the fossils supports Ferreira''s taxonomic identification rather than undermining his broader claim about local growth.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GY9OJI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "cultivated" most nearly mean?', E'In a 2019 study of urban green spaces in Reykjavik, researchers found that residents who regularly visited municipal gardens cultivated a stronger sense of community belonging. The gardens served not only as sites for growing vegetables but also as gathering places where neighbors exchanged recipes and organized seasonal festivals.', $lyceon_json$[{"key":"A","text":"developed"},{"key":"B","text":"plowed"},{"key":"C","text":"harvested"},{"key":"D","text":"decorated"}]$lyceon_json$::jsonb, 'A', NULL, E'In the passage, "cultivated" describes residents gradually building or developing a stronger sense of community belonging over time. The word "developed" captures this meaning of fostering something intangible through sustained effort. "Plowed" refers to turning soil with a blade, which is a physical agricultural action that cannot logically apply to a sense of belonging. "Harvested" means to gather crops that are already mature, implying collection rather than gradual growth, and a feeling cannot be gathered like produce. "Decorated" means to adorn or embellish an object or space, which has no connection to the process of building an emotional or social bond.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HIIVZP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'Economist Lina Karim has argued that microfinance institutions in rural Bangladesh do not simply provide capital to underserved borrowers; they also reshape local credit hierarchies by displacing informal moneylenders whose interest rates can exceed 120 percent annually. However, Karim cautions that this displacement may create a dependency on institutional lending cycles that villagers cannot easily exit, thereby substituting one form of financial constraint for another.', $lyceon_json$[{"key":"A","text":"It introduces a qualification that complicates the positive assessment presented in the first sentence."},{"key":"B","text":"It provides statistical evidence that strengthens the claim made in the first sentence."},{"key":"C","text":"It describes a historical event that preceded the development discussed in the first sentence."},{"key":"D","text":"It offers an alternative explanation for a phenomenon that the first sentence attributes to a single cause."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence presents microfinance in a broadly positive light—providing capital and displacing exploitative moneylenders. The second sentence, introduced by "However," then complicates this picture by warning that institutional dependency may replace one financial constraint with another. This is a classic qualification: acknowledging a benefit while raising a significant caveat. The option about providing statistical evidence is wrong because the second sentence contains no numbers or data; the statistic about 120 percent interest appears in the first sentence, not the second. The option about describing a prior historical event is wrong because the second sentence discusses a concurrent or subsequent risk of the same microfinance phenomenon, not an earlier event. The option about offering an alternative explanation is wrong because the second sentence does not propose a different cause for the same effect; rather, it identifies an additional negative consequence of the development already described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HU16WY', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "eclipse" most nearly mean?', E'Historian Renata Voss argues that the administrative reforms enacted by Empress Theodora in 548 CE did not merely complement Justinian''s legal codification but threatened to eclipse it in practical impact. While the Codex systematized Roman law on parchment, Theodora''s restructuring of provincial tax collection altered the daily fiscal realities of millions of subjects across three continents.', $lyceon_json$[{"key":"A","text":"surpass"},{"key":"B","text":"obscure"},{"key":"C","text":"imitate"},{"key":"D","text":"terminate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage sets up a comparison of practical impact between two historical achievements, stating that Theodora''s reforms threatened to exceed Justinian''s codification in their real-world consequences. "Surpass" means to exceed in degree or magnitude, which matches the passage''s claim about comparative practical impact. "Obscure" means to make unclear or hide from view; while an astronomical eclipse does block light, the passage is not arguing that Theodora''s reforms concealed or made Justinian''s work invisible—it is arguing they exceeded it in effect. The codification remained well known; the claim is about relative magnitude, not visibility. "Imitate" means to copy or replicate, but the passage explicitly contrasts the two achievements as different in kind (legal codification versus tax-collection restructuring), so copying is incoherent. "Terminate" means to bring to an end, but the passage does not suggest Theodora''s reforms ended or abolished Justinian''s codification—both coexisted, with the argument being about which had greater practical reach.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I4XF8B', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the Andaman Sea have documented a 37% decline in reef-building coral species over the past nineteen years. _______ the decline has prompted regional governments to establish seven new marine protected areas since 2021.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a documented decline in coral species and then states that governments have responded by creating marine protected areas. This is a cause-and-effect relationship: the decline prompted the protective action. "Accordingly" correctly signals that the second sentence follows as a logical consequence of the first. "Nevertheless" incorrectly implies a contrast or concession, suggesting the government action happened despite the decline rather than because of it. "In contrast" wrongly signals opposition between two ideas that are actually causally linked. "Specifically" incorrectly suggests the second sentence is providing a narrower detail about the decline itself, when it is actually describing a separate consequential action.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IROK4Z', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2K86MOW', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Fumiko Tanabe unearthed a series of obsidian tools at a remote site in Hokkaido. The tools, which date to roughly 14,000 BCE, bear markings unlike any previously _______ Tanabe has argued that they represent a previously unknown manufacturing technique developed by early Jomon settlers.', $lyceon_json$[{"key":"A","text":"documented;"},{"key":"B","text":"documented,"},{"key":"C","text":"documented"},{"key":"D","text":"documented:"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank falls between two independent clauses: the first describes the tools'' markings, and the second presents Tanabe''s argument about them. A semicolon correctly joins two independent clauses without a coordinating conjunction. Using a comma after ''documented'' creates a comma splice, which is a boundary error. Omitting punctuation entirely produces a run-on sentence. A colon would be grammatically possible only if the second clause explained or elaborated on the first, but here the second clause introduces an argument rather than defining or listing what ''previously documented'' means, making the semicolon the correct and unambiguous choice.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KC2M4U', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing for an academic audience and wants to present a nuanced contrast between two competing explanations for colony collapse disorder in honeybees. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
