INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M4MYOM', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Geochemist Clara Devereaux has proposed that the high concentrations of iridium found in certain deep-ocean sediment layers do not necessarily indicate asteroid impacts, as has long been assumed. Devereaux notes that volcanic eruptions from deep-mantle plumes can also deliver iridium to the Earth''s surface in significant quantities. She points to the Deccan Traps, a massive volcanic province in present-day India, which was actively erupting around the same time as the Chicxulub asteroid impact 66 million years ago. Devereaux argues that distinguishing between volcanic and extraterrestrial iridium sources requires analyzing the ratios of iridium to other platinum-group elements, since mantle-derived and meteoritic materials exhibit distinct elemental signatures.', $lyceon_json$[{"key":"A","text":"The Deccan Traps eruptions, not the Chicxulub impact, were the primary cause of the mass extinction event 66 million years ago."},{"key":"B","text":"Devereaux has developed a method for identifying whether iridium in sediment layers originated from volcanic activity or from asteroid impacts."},{"key":"C","text":"Devereaux challenges the automatic association of iridium anomalies with asteroid impacts and proposes a geochemical method to differentiate sources."},{"key":"D","text":"Iridium concentrations in ocean sediments are unreliable indicators of any geological event because multiple processes can deposit the element."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents two linked ideas: Devereaux''s challenge to the default assumption that iridium signals asteroid impacts, and her proposal that platinum-group element ratios can distinguish volcanic from extraterrestrial sources. The option combining both elements captures the full main idea. The option about the Deccan Traps causing the mass extinction goes beyond anything Devereaux claims in the passage; she discusses iridium sourcing, not the cause of the extinction itself. The option describing a method alone captures only the second half of Devereaux''s argument without the critical challenge to existing assumptions. The option calling iridium concentrations unreliable overstates the argument; Devereaux does not say iridium is unreliable, only that its source must be determined more carefully.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MJ2Z0T', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the function of the text as a whole?', E'The fruit fly Drosophila melanogaster has served as a model organism in genetics for over a century, but behavioral ecologist Priya Sundaram contends that this reliance has introduced systematic blind spots. Because Drosophila thrives in laboratory conditions and reproduces rapidly, researchers have favored it for studies of gene expression, circadian rhythms, and neural development. Sundaram argues, however, that Drosophila''s unusual tolerance for inbreeding and its compressed life cycle make it a poor proxy for understanding how genetic variation operates in longer-lived, outbreeding species. She does not advocate abandoning Drosophila research but instead proposes that findings from Drosophila studies be systematically cross-validated against data from organisms such as the zebrafish and the deer mouse, which more closely mirror the population structures of most vertebrates.', $lyceon_json$[{"key":"A","text":"It presents a researcher's critique of an established scientific practice and describes the modification she recommends."},{"key":"B","text":"It traces the historical development of Drosophila research and explains why the organism was originally selected as a model."},{"key":"C","text":"It contrasts two researchers' opposing views on whether Drosophila studies should continue to receive funding."},{"key":"D","text":"It argues that zebrafish and deer mice should replace Drosophila as the primary model organisms in genetics research."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces Sundaram''s critique of over-reliance on Drosophila and then presents her recommended adjustment — cross-validating Drosophila findings against other organisms. The option describing a critique plus a recommended modification captures both elements. The option about tracing historical development addresses only the background information in the first sentence and misses the argumentative core. The option about two researchers'' opposing views is inaccurate because only one researcher, Sundaram, is presented; no opposing figure appears. The option claiming zebrafish and deer mice should replace Drosophila overstates Sundaram''s position, since she explicitly does not advocate abandoning Drosophila research but rather supplementing it with cross-validation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NGTUCA', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The architect Lina Mossberg designed a municipal library in Tromsø, Norway, that features triple-glazed windows angled at 53 degrees to capture maximum winter light. The building''s geothermal heating system reduces energy consumption by 61% compared to conventional structures. _______ the library''s cantilevered reading rooms extend over an adjacent birch grove, allowing visitors to read among the treetops without disturbing the forest floor.', $lyceon_json$[{"key":"A","text":"Additionally,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"On the other hand,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage lists distinct architectural features of the library: angled windows for light, a geothermal heating system, and cantilevered reading rooms over a birch grove. The third sentence introduces yet another independent design feature, so the relationship is additive. "Additionally" correctly signals that another parallel feature is being introduced. "Consequently" wrongly implies the reading rooms are a result of the geothermal system, but no causal link exists between these features. "On the other hand" incorrectly introduces a contrast, yet the reading rooms do not oppose or counterbalance the heating system. "In other words" wrongly suggests the third sentence is restating the second in different language, when it is actually presenting an entirely separate feature.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NSO133', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleoclimatologist Adaeze Okafor analyzed pollen cores extracted from a peat bog in County Galway, Ireland. Her analysis revealed that a severe cold period around 6200 BCE caused widespread oak forest _______ the forests recovered within roughly 150 years, the genetic bottleneck that the dieback imposed permanently altered the regional oak population''s diversity.', $lyceon_json$[{"key":"A","text":"dieback; consequently,"},{"key":"B","text":"dieback. While"},{"key":"C","text":"dieback, while"},{"key":"D","text":"dieback; for example,"}]$lyceon_json$::jsonb, 'B', NULL, E'After the blank, the text presents a concessive relationship: the forests recovered (concession), yet the genetic bottleneck permanently altered diversity (main point). The subordinating conjunction ''While'' introduces the concessive clause as dependent, and starting a new sentence with a period before ''While'' correctly closes the preceding independent clause about forest dieback. Using a semicolon with ''consequently'' creates a proper boundary but misrepresents the logical relationship — the second clause is not a consequence of forest dieback but rather a concession-and-contrast structure. Using a comma with ''while'' produces a comma splice between the independent clause about the cold period causing dieback and the clause that follows. Using a semicolon with ''for example'' creates a proper boundary but the second clause is not an example of forest dieback; it contrasts recovery against lasting genetic change.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q5VJ0N', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Tomoko Ishida has investigated how the brain processes conflicting sensory signals during locomotion. In her experiments, participants walked on a treadmill while wearing a virtual-reality headset that displayed a corridor moving at a speed different from their actual walking pace. When the visual scene moved faster than the participants were walking, most participants unconsciously increased their walking speed to match the visual flow; when the scene moved slower, they decelerated. Ishida observed, however, that participants who had undergone vestibular rehabilitation for inner-ear disorders did not show this automatic speed adjustment. These participants maintained a steady walking pace regardless of the visual scene''s speed. Ishida argues that this contrast suggests that ________', $lyceon_json$[{"key":"A","text":"the automatic gait adjustment observed in most participants depends on integration between visual input and vestibular feedback, and that vestibular rehabilitation alters how the brain weights these competing signals."},{"key":"B","text":"participants who had undergone vestibular rehabilitation were unable to perceive the visual scene displayed by the virtual-reality headset during the experiment."},{"key":"C","text":"the virtual-reality display used in the experiment was not realistic enough to produce sensory conflict in participants with prior exposure to similar technology."},{"key":"D","text":"visual processing speed is primarily determined by vestibular function, and damage to the inner ear permanently eliminates the brain's ability to interpret visual motion."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that most participants automatically adjusted gait to match visual flow, but vestibular-rehabilitation participants did not. The most logical inference is that automatic adjustment requires integration of visual and vestibular signals, and rehabilitation changed how the brain prioritizes these inputs. The claim that rehabilitation participants could not perceive the visual scene is unsupported and implausible; the passage describes altered motor response, not perceptual blindness. The claim about the headset lacking realism is contradicted by the fact that most participants did respond to the visual display, confirming its effectiveness at producing sensory conflict. The claim that vestibular function determines visual processing and that inner-ear damage eliminates visual motion interpretation vastly overstates the findings; the passage discusses gait adjustment in response to conflicting signals, not a wholesale loss of visual motion perception.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QC2XNG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A collaborative study by researchers at the Tromsø Geophysical Observatory examined how solar wind fluctuations affect auroral intensity at high latitudes. The study concluded that neither the velocity of charged particles nor the density of the solar plasma _______ sufficient on its own to predict the brightness of an auroral display; rather, the interaction between the two variables determines the outcome.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"were"},{"key":"C","text":"is"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject uses the correlative conjunction ''neither...nor,'' which requires the verb to agree in number with the noun nearest to it — in this case, ''density,'' a singular noun. The passage uses present-tense narration within the reported conclusion (''determines the outcome''), so the verb should also be in the present tense. The singular present-tense form ''is'' correctly agrees with ''density'' and maintains tense consistency. ''Are'' is plural and violates the neither-nor proximity agreement rule. ''Were'' is plural past tense, failing both in number agreement and tense consistency. ''Have been'' is plural present perfect, again failing in number agreement with the singular nearer subject.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TQOY7E', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The glassblower Marguerite Ducasse was renowned in 1920s Lyon for vessels whose brilliance rivaled Venetian imports. Yet her ambition was always tempered by a meticulous attention to structural soundness; she would destroy any piece, however luminous, that failed her tap test for hidden fractures.', $lyceon_json$[{"key":"A","text":"moderated"},{"key":"B","text":"heated"},{"key":"C","text":"provoked"},{"key":"D","text":"abandoned"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Ducasse''s ambition was kept in check by her commitment to structural integrity—she would sacrifice beautiful pieces rather than compromise on soundness. "Moderated" captures this meaning of restraining or balancing one quality with another. "Heated" relates to the metallurgical or glassmaking sense of tempering through high temperature, but the sentence is not describing a physical process applied to ambition; it describes a psychological balance. "Provoked" means to incite or stimulate, which is the opposite of the restraining relationship the passage describes between attention to soundness and ambition. "Abandoned" means to give up entirely, but the passage shows Ducasse still pursued ambitious brilliance—she simply constrained it, not discarded it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TR99RP', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Geochemist Raul Espinoza has proposed that sulfur isotope ratios in Archean-era sedimentary rocks can serve as reliable proxies for atmospheric oxygen _______ other researchers have pointed out that diagenetic alteration can scramble these isotopic signatures, Espinoza maintains that careful sample selection from unmetamorphosed strata mitigates this concern.', $lyceon_json$[{"key":"A","text":"levels. Although"},{"key":"B","text":"levels; however,"},{"key":"C","text":"levels, although"},{"key":"D","text":"levels, however,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence after the blank contains two parts: a concessive clause (''other researchers have pointed out...'') and a main clause (''Espinoza maintains...''). The word ''although'' is a subordinating conjunction that turns the researchers'' objection into a dependent clause, which is then properly followed by the independent main clause about Espinoza''s response. Starting a new sentence with ''Although'' correctly closes the first independent clause with a period and introduces the concessive structure. Using a semicolon with ''however'' creates a grammatically correct boundary but misrepresents the logical relationship: ''however'' would make both clauses independent and contradict the concessive structure that leads to Espinoza''s rebuttal. Using a comma with ''although'' produces a comma splice between the first independent clause and what follows. Using a comma with ''however'' similarly produces a comma splice while also misrepresenting the logical relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VTEEBV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleontologist Rina Chakravarti argues that the extinction of large-bodied titanosaurs in the late Cretaceous was driven primarily by volcanic activity in the Deccan Traps region. Her analysis of bone-bed geochemistry across 43 sites in central India shows elevated iridium and sulfur isotope ratios consistent with prolonged volcanic winters. _______ several of Chakravarti''s own datasets reveal that titanosaur populations in what is now Patagonia were already declining at least 400,000 years before the main phase of Deccan volcanism began.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"However,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first two sentences present Chakravarti''s claim that volcanic activity caused titanosaur extinction, supported by geochemical evidence. The third sentence then introduces a complication from her own data: Patagonian titanosaurs were declining well before the volcanism began, which undermines the claim that volcanism was the primary driver. This is a concessive or adversative relationship. "However" correctly signals that the upcoming information qualifies or challenges the preceding argument. "Moreover" incorrectly suggests the Patagonian data adds further support to the volcanic hypothesis, when in fact it undercuts it. "For instance" wrongly implies the Patagonian decline is an example illustrating the volcanic-cause theory, but it actually contradicts the timeline. "Similarly" incorrectly suggests a parallel finding, when the Patagonian data presents a conflicting timeline rather than a corroborating one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W1Z0HD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economist Priya Narasimhan has demonstrated that microfinance programs in rural Tamil Nadu increased women''s household decision-making authority by 29% over a six-year period. Critics have countered that this metric reflects only self-reported survey data and may overstate actual shifts in domestic power dynamics. _______ Narasimhan''s longitudinal tracking of 1,400 households reveals that women who received microloans were also 3.1 times more likely to independently register land titles—a legally verifiable indicator of decision-making authority that does not rely on self-reporting.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"Granted,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents a three-part argumentative structure: Narasimhan''s original finding, critics'' objection about self-reported data, and then Narasimhan''s rebuttal with independently verifiable evidence (land title registrations). The blank introduces a sentence that counters the critics'' objection by offering objective data, so the transition must signal that the upcoming information pushes back against the criticism. "Nonetheless" correctly signals that despite the critics'' valid concern about self-reporting, additional evidence supports Narasimhan''s broader claim. "In addition" wrongly suggests the third sentence merely adds a parallel point rather than responding to the criticism; the land-title data is specifically marshaled as a rebuttal, not as supplementary information. "Granted" is a concessive transition that acknowledges a point before pivoting away from it, but the third sentence is not conceding the critics'' point—it is refuting it with harder evidence, making concession the wrong rhetorical move. "For example" incorrectly implies the land-title finding is an illustration of the critics'' concern about self-reporting, when it is actually evidence that contradicts their objection by providing a non-self-reported measure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W4330Q', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WN0IE0', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student wants to emphasize the unexpected scope of Haruki Murakami''s translation work to an audience already familiar with his novels. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZUGN4Y', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Farallon Institute have hypothesized that the recent decline in Cassin''s auklet populations along the northern California coast is driven primarily by a reduction in the availability of krill, the small crustacean that constitutes the auklets'' principal food source. The researchers note that ocean temperatures in the region have risen by 1.4 degrees Celsius over the past two decades, and they suspect that warmer waters have pushed krill populations deeper or farther north, beyond the auklets'' typical foraging range.', $lyceon_json$[{"key":"A","text":"Cassin's auklet colonies in Alaska, where krill remains abundant near the surface, have maintained stable population numbers over the same period."},{"key":"B","text":"Ocean temperatures along the northern California coast have fluctuated in similar patterns during previous decades without affecting auklet populations."},{"key":"C","text":"Several other seabird species that do not depend on krill have also declined in the same coastal region."},{"key":"D","text":"Cassin's auklets have been observed nesting in new locations farther south along the California coast in recent years."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that reduced krill availability is driving auklet decline. The finding that auklet colonies remain stable where krill is still abundant directly supports this causal link: where the proposed cause is absent, the effect is also absent. The finding about past temperature fluctuations not affecting populations would undermine, not support, the hypothesis by suggesting temperature changes alone do not predict auklet decline. The finding about other non-krill-dependent seabirds declining would suggest a cause unrelated to krill, weakening the specific hypothesis. The finding about auklets nesting farther south does not address krill availability or population decline and could be consistent with many different explanations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
